head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/calendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
scwin.vScrenID = "ULDCOM91003_10.xml";
scwin.gLdMktTp = js_market;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
}; // 세션의 시장구분

scwin.fn_undo = function() {
    dts_DocList.undoAll();
};
scwin.fn_SetMktCode = function() {
    // 세션ID의 시장정보를 셋팅한다.

    //	rdo_MktTpCd.Format="9^전체,1^유가,2^코스닥,6^코넥스";
    //	rdo_MktTpCd.style.backgroundColor = "#d9e9fc";	
    //	rdo_MktTpCd.Reset();

    $c.stf.setObjectValue(rdo_MktTpCd, scwin.gLdMktTp);
};
scwin.fn_SetCode = function() {
    // 대분류 셋팅
    dts_FormUpclss.DataID = "/CodeAction.do?method=listFormUpclss&For=R";
    dts_FormUpclss.Reset();

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

};X < !국문--;
보고서;
찾기-- > function() {
    var url = "/DocSearch.do?method=listKoreanDoc&inputMessageId=KORFORM_IN&outputMessageId=KORFORM_OUT" + "&FORMNM=" + txb_FormNm.getValue() + "&MKTTPCD=" + rdo_MktTpCd.getValue() + "&FORM_UPCLSS_CD=" + $c.cp.valueOfIndex(cmb_FormUpclssCd, "VALUE", cmb_FormUpclssCd.getSelectedIndex()) + "&RSN_CLSS_CD=" + $c.cp.valueOfIndex(cmb_RsnClssCd, "VALUE", cmb_RsnClssCd.getSelectedIndex()) + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_DocList.DataID = encodeURI(url);
    dts_DocList.reset();
    //fn_undo();

};
scwin.fn_SetParam = function(GridID, row, colid) {
    var parentWin = $c.frame.path("../");
    var objDataID = document.all(GridID.DataID); // 가져오는 방식이 좀 특이하다..

    var vFORM_CD = objDataID.getCellData(row, "FORM_CD");
    var vFORM_VER = objDataID.getCellData(row, "FORM_VER");
    var vFORM_KOR_NM = objDataID.getCellData(row, "FORM_KOR_NM");
    var vFORM_ENG_NM = objDataID.getCellData(row, "FORM_ENG_NM");
    if (typeof(parentWin.txb_FORM_CD) == "object") {
        $c.stf.setObjectValue(parentWin.txb_FORM_CD, vFORM_CD);
    }
    if (typeof(parentWin.txb_FORM_VER) == "object") {
        $c.stf.setObjectValue(parentWin.txb_FORM_VER, vFORM_VER);
    }
    if (typeof(parentWin.txb_FORM_KOR_NM) == "object") {
        $c.stf.setObjectValue(parentWin.txb_FORM_KOR_NM, vFORM_KOR_NM);
    }
    if (typeof(parentWin.txb_FORM_ENG_NM) == "object") {
        $c.stf.setObjectValue(parentWin.txb_FORM_ENG_NM, vFORM_ENG_NM);
    }
};
scwin.fn_resizeToWin = function() {
    frame.Width = 500;
    frame.Height = 500;
};
scwin.txb_FormNm_onkeydown = function() {
    if (window.event.keyCode == "13") {
        fn_Search();
    }
};
scwin.dts_DocList_OnLoadError = function() {
    $c.stf.alert_error(dts_DocList);
};
scwin.dts_DocList_OnLoadCompleted = function(rowcount) {
    if (dts_DocList.errorMsg) {
        $c.win.alert(dts_DocList.errorMsg);
    } else {
        txb_TotalCnt.setValue("총 " + rowcount + "건");
    }
};
scwin.grd_DocList_OnDblClick = async function(row, colid) {
    //fn_SetParam(grd_DocList, row, colid);

    // 부모창에 데이타 셋팅
    frame.opener.txb_FormCd.setValue(dts_DocList.getCellData(row, "FORM_CD"));
    frame.opener.txb_FormNm.setValue(dts_DocList.getCellData(row, "FORM_KOR_NM"));
    await $c.frame.CloseFrame();
};
scwin.img_Search_onclick = function() {
    fn_Search();
};
scwin.img_close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.dts_FormUpclss_OnLoadCompleted = function(rowcount) {
    $c.stf.setObjectValue(cmb_FormUpclssCd, "10");
};
scwin.cmb_FormUpclssCd_OnSelChange = function() {
    vFormUpclssCd = $c.cp.valueOfIndex(cmb_FormUpclssCd, "VALUE", cmb_FormUpclssCd.getSelectedIndex());
    if (vFormUpclssCd == '') {
        cmb_RsnClssCd.setDisabled(true);
    } else {
        cmb_RsnClssCd.setDisabled(false);
        //cmb_RsnClssCd.ShowList();

    }

    // 대분류에 해당하는 사유분류리스트  셋팅
    dts_Rsnclss.DataID = "/CodeAction.do?method=listDisclsRsnclss&inputMessageId=FORMUPCLSS_IN&outputMessageId=CODE_OUT" + "&FOR=R&FORMUPCLSSCD=" + vFormUpclssCd;
    dts_Rsnclss.Reset();
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.libRoundPanel.PanelToGroupBox(panel_1);
    // 대분류 콤보에 값 셋팅
    scwin.fn_SetCode();

    // 세션값에서 로그인한 사람의 세션값을 읽어와서 사용할 시장구분에 셋팅한다.	
    scwin.fn_SetMktCode();
    fn_Search();
    //n_resizeToWin();

};
